tasks = []# Display the main menudef main_menu():    while True:        print("""              --- Main Menu ---              [1]. Add task              [2]. Show tasks              [3]. Delete tasks              [4]. Quit program              """)        navigate = input("Select an option: ").strip()        if navigate == "1":            add_task(tasks)        elif navigate == "2":            show_tasks(tasks)        elif navigate == "3":            delete_task(tasks)        elif navigate == "4":            print("Quitting program...")            break        else:            print("Invalid option, please try again.")# Add task to the listdef add_task(tasks):    task = input("Enter task: ")    tasks.append(task)    print("Task added successfully")    input("press Enter to return to the main menu.")#Show all tasks in the listdef show_tasks(tasks):    if tasks:        print("Your tasks:")        for i, task in enumerate(tasks, 1):              print(f"{i}. {task}")    else:        print("No tasks available.")    input("press Enter to return to the main menu.")# Delete a task from the list    def delete_task(tasks):    if not tasks:        print("No tasks to delete.")        return    while True:        try:            user_input = input("Task number to delete: ").strip()                        if user_input.lower() == "exit":                print("Returning to main menu...")                break                        task = int(user_input)                    if 1 <= task <= len(tasks):                tasks.pop(task - 1)                print("Task deleted.")                break            else:                print("Invalid task number, please try again or type 'exit' to return.")        except (ValueError, IndexError):            print("Invalid task number, please try again or type 'exit' to return.") # Start the programmain_menu()